record.field:
result = min(per, balance) if covers_month_end else 0
if covers_month_end and 0.005 < balance - result < per:
    result = balance

result = min(per, balance) if covers_15th else 0
if covers_15th and 0.005 < balance - result < per:
    result = balance

result = min(per * 2, balance)
if 0.005 < balance - result < per:
    result = balance
